function apply_patient_territory_filters() {
  // Region field (top-level under Somalia, groups only)
  const df_region = frappe.meta.get_docfield("Patient", "region");
  if (df_region) {
    df_region.get_query = () => ({
      filters: {
        parent_territory: "Somalia",
        is_group: 1,
      },
    });
  }

  // Territory/District field (children of selected region)
  const df_territory = frappe.meta.get_docfield("Patient", "territory");
  if (df_territory) {
    df_territory.get_query = (doc) => {
      if (!doc.region) {
        return { filters: { name: ["=", ""] } };
      }
      return {
        filters: {
          parent_territory: doc.region,
          // is_group: 0, // uncomment if you want leaf only
        },
      };
    };
  }
}

apply_patient_territory_filters();

frappe.ui.form.on("Patient", {
  setup(frm) {
    // still fine to call, but meta-based query is what makes Quick Entry work
    apply_patient_territory_filters();
  },

  region(frm) {
    frm.set_value("territory", null);
  },
});

