                            frappe.model.set_value(cdt, cdn, 'medical_department', r.message.medical_department);
                            frm.refresh_field('package_prescription'); // Refresh the child table to show changes
                        }
                    })
                    .catch(error => {
                        console.log("Error fetching departments:", error);
                    });
            }
        },
})

frappe.ui.form.on('Clinical Procedure', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 1 && !frm.doc.transferred_to_recovery) {

            frm.add_custom_button(__('Transfer To Recovery'), function () {

                // Map child table rows
                let treatment_plann = [];

                if (frm.doc.treatment_plan) {
                    frm.doc.treatment_plan.forEach(row => {
                        treatment_plann.push({
                            drug_code: row.drug_code,
                            quantity: row.quantity,
                            dosage_form: row.dosage_form,
                            period: row.period
                        });
                    });
                }

                frappe.db.insert({
                    doctype: 'Recovery',
                    patient: frm.doc.patient,
                    patient_name: frm.doc.patient_name,
                    practitioner: frm.doc.practitioner,
                    procedure_template: frm.doc.procedure_template,
                    procedure_date: frm.doc.procedure_date,
                    post_operative: frm.doc.post_operative_note,

                    // Child table
                    treatment_plann: treatment_plann
                }).then(() => {

                    frappe.db.set_value(
                        'Clinical Procedure',
                        frm.doc.name,
                        'transferred_to_recovery',
                        1
                    ).then(() => {
                        frappe.show_alert({
                            message: __("Patient Successfully Transferred into Recovery"),
                            indicator: 'green'
                        }, 3);

                        frm.reload_doc();
                    });

                });
            }).addClass("btn-primary");
        }
    }
});


