frappe.ui.form.on("Patient", {
  p_age(frm) {
    sync_dob_from_age(frm);
  },
  age_type(frm) {
    sync_dob_from_age(frm);
  },
  dob(frm) {
    sync_age_from_dob(frm);
  },
});

async function sync_dob_from_age(frm) {
  if (frm.__age_syncing) return;

  const age_type = (frm.doc.age_type || "").trim(); // Year/Month/Day
  const age = parseInt(frm.doc.p_age, 10);

  if (!age_type || !Number.isFinite(age) || age <= 0) return;

  frm.__age_syncing = true;
  try {
    const today = moment(frappe.datetime.get_today(), "YYYY-MM-DD");
    let dob;

    if (age_type === "Year") {
      dob = today.clone().subtract(age, "years").startOf("year");
    } else if (age_type === "Month") {
      dob = today.clone().subtract(age, "months").startOf("month");
    } else if (age_type === "Day") {
      dob = today.clone().subtract(age, "days");
    } else {
      return;
    }

    await frm.set_value("dob", dob.format("YYYY-MM-DD"));
  } finally {
    frm.__age_syncing = false;
  }
}

async function sync_age_from_dob(frm) {
  if (frm.__age_syncing) return;
  if (!frm.doc.dob) return;

  frm.__age_syncing = true;
  try {
    const today = moment(frappe.datetime.get_today(), "YYYY-MM-DD");
    const dob = moment(frm.doc.dob, "YYYY-MM-DD");

    if (!dob.isValid()) return;
    if (dob.isAfter(today)) {
      await frm.set_value("p_age", null);
      return;
    }

    const years = today.diff(dob, "years");
    const months = today.diff(dob, "months");
    const days = today.diff(dob, "days");

    if (years >= 2) {
      await frm.set_value("age_type", "Year");
      await frm.set_value("p_age", years);
    } else if (months >= 1) {
      await frm.set_value("age_type", "Month");
      await frm.set_value("p_age", months);
    } else {
      await frm.set_value("age_type", "Day");
      await frm.set_value("p_age", days);
    }
  } finally {
    frm.__age_syncing = false;
  }
}

