    },
    additional_discount_percentage(frm) {
        calculate_totals(frm, true);
    }
});

function calculate_totals(frm, from_percentage = false, from_amount = false) {
    let total = 0;
    (frm.doc.canteen_item || []).forEach(row => {
        total += (row.amount || 0);
    });
    total = round2(total);
    frm.set_value("net_total", total);

    let discount_percentage = frm.doc.additional_discount_percentage || 0;
    let discount_amount = frm.doc.discount_amount || 0;

    // Case 1: triggered by percentage or items change
    if (from_percentage || !from_amount) {
        discount_amount = round2((total * discount_percentage) / 100);
        frm.set_value("discount_amount", discount_amount);
    }
    // Case 2: triggered by manual discount amount edit → recalc percentage
    else if (from_amount && total > 0) {
        discount_percentage = round2((discount_amount / total) * 100);
        frm.set_value("additional_discount_percentage", discount_percentage);
    }

    let grand_total = round2(total - discount_amount);
    frm.set_value("grand_total", grand_total);

    // Keep "percentage" always equal to "additional_discount_percentage"
    frm.set_value("percentage", discount_percentage);

    frm.refresh_fields([
        "net_total",
        "discount_amount",
        "grand_total",
        "additional_discount_percentage",
        "percentage"
    ]);
}

// 🔹 Utility function to ensure 2-decimal precision
function round2(value) {
    return Math.round((value + Number.EPSILON) * 100) / 100;
}

