    discount_amount: function(frm) {
        calculate_and_update_discount(frm, 'amount');
    },

    additional_discount_percentage: function(frm) {
        calculate_and_update_discount(frm, 'percentage');
    },
});

function calculate_and_update_discount(frm, type) {
    let party_balance = frm.doc.party_balance || 0;
    let discount_amount = 0;
    let discount_percentage = 0;

    if (type === 'amount') {
        discount_amount = frm.doc.discount_amount || 0;
        discount_percentage = party_balance ? (discount_amount / party_balance) * 100 : 0;
    } else if (type === 'percentage') {
        discount_percentage = frm.doc.additional_discount_percentage || 0;
        discount_amount = (discount_percentage / 100) * party_balance;
    }

    // Update fields so they stay in sync
    frm.set_value('discount_amount', discount_amount);
    frm.set_value('additional_discount_percentage', discount_percentage);
    frm.set_value('percentage', discount_percentage);

    // Update or remove deduction row
    update_payment_entry_deduction(frm, discount_amount);
}

async function update_payment_entry_deduction(frm, discount_amount) {
    // Get the account (either from memory or fetch again if missing)
    let discount_account = frm.discount_account || 
        await frappe.db.get_single_value('HIS Settings', 'discount_account');

    if (!discount_account) {
        frappe.msgprint(__('Please set a Discount Account in HIS Settings.'));
        return;
    }

    // Find existing row
    let existing_row = frm.doc.deductions.find(row => row.account === discount_account);

    if (discount_amount > 0) {
        if (existing_row) {
            existing_row.amount = discount_amount;
        } else {
            let new_row = frm.add_child('deductions');
            new_row.account = discount_account;
            new_row.amount = discount_amount;
        }
    } else {
        if (existing_row) {
            let idx = frm.doc.deductions.indexOf(existing_row);
            frm.doc.deductions.splice(idx, 1);
        }
    }

    frm.refresh_field('deductions');
}

