(() => {
  const DOCTYPE = "Hajj Screening"; // <-- CHANGE THIS (example: "Hajj Screening")

  // prevent double registration on reloads
  if (window.__YN_EXCLUSIVE_REGISTERED?.[DOCTYPE]) return;
  window.__YN_EXCLUSIVE_REGISTERED = window.__YN_EXCLUSIVE_REGISTERED || {};
  window.__YN_EXCLUSIVE_REGISTERED[DOCTYPE] = true;

  function find_yes_no_pairs() {
    const meta = frappe.get_meta(DOCTYPE);
    const checks = (meta.fields || [])
      .filter(df => df.fieldtype === "Check" && df.fieldname)
      .map(df => df.fieldname);

    const set = new Set(checks);
    const pairs = [];

    // Pattern 1: yes1/no1, yes2/no2...
    for (const f of checks) {
      const m = f.match(/^yes(\d+)$/i);
      if (!m) continue;
      const i = m[1];
      const y = `yes${i}`;
      const n = `no${i}`;
      if (set.has(y) && set.has(n)) pairs.push([y, n]);
    }

    // Pattern 2: prefix_yes / prefix_no
    for (const f of checks) {
      const m = f.match(/^(.*)_yes$/i);
      if (!m) continue;
      const prefix = m[1];
      const y = `${prefix}_yes`;
      const n = `${prefix}_no`;
      if (set.has(y) && set.has(n)) pairs.push([y, n]);
    }

    // de-dup
    const uniq = [];
    const seen = new Set();
    for (const [y, n] of pairs) {
      const key = `${y}__${n}`;
      if (seen.has(key)) continue;
      seen.add(key);
      uniq.push([y, n]);
    }
    return uniq;
  }

  const pairs = find_yes_no_pairs();

  // If you want to confirm it found your fields, uncomment:
  // console.log("[YN Exclusive] pairs:", pairs);

  const handlers = {
    setup(frm) {
      frm._yn_lock = false;
    }
  };

  for (const [yes_f, no_f] of pairs) {
    handlers[yes_f] = function (frm) {
      if (frm._yn_lock) return;
      frm._yn_lock = true;

      if (frm.doc[yes_f]) {
        frm.set_value(no_f, 0);
      }

      frm._yn_lock = false;
    };

    handlers[no_f] = function (frm) {
      if (frm._yn_lock) return;
      frm._yn_lock = true;

      if (frm.doc[no_f]) {
        frm.set_value(yes_f, 0);
      }

      frm._yn_lock = false;
    };
  }

  frappe.ui.form.on(DOCTYPE, handlers);
})();
